#include "shop_orders/task_shop_order_sources.hpp"
// 责任仍由原合同、受托物和垫款事实持有；这里只投影具名来源，不创设免责或第二账本。
#include "task_actor_pending_responsibilities.hpp"
#include "resident/domains/tasks/task_personal_advance_rules.hpp"
#include <set>
namespace hanmo::resident { namespace {
bool person(const Owner& value,const StableId& id){return value.kind==Owner::Kind::actor&&value.id==id;}
bool person(const SubjectRef& value,const StableId& id){return value.kind==SubjectKind::actor&&value.id==id;}
bool terminal(const TaskRecord& task){return task.status=="success"||task.status=="failed"||task.status=="cancelled";}
}
Outcome<TaskActorPendingResponsibilities> read_task_actor_pending_responsibilities(const CommonStore& c,const TaskState& tasks,const TaskCatalog& catalog,const StableId& actor){
    const auto fail=[](const StableId& code,const StableId& id)->Outcome<TaskActorPendingResponsibilities>{return {false,{},common_failure(code,id).error};};if(!c.actor(actor))return fail("UnknownTaskResponsibilityActor",actor);TaskActorPendingResponsibilities out{c.state().identity,actor,{}};std::set<StableId> emitted,related;
    auto pending=[&](const StableId& id){if(emitted.insert(id).second)out.pending_source_ids.push_back(id);};
    for(const auto& row:tasks.tasks.rows()){const auto& task=row.second;const auto* definition=resolve_task_definition(tasks,catalog,task);const auto* contract=task.contract_id?tasks.contracts.find(*task.contract_id):nullptr;if(task.id!=row.first||(task.contract_id&&!contract))return fail("InvalidTaskResponsibilitySource",row.first);const bool involved=task.assignee==actor||(definition&&person(definition->issuer,actor))||(contract&&(person(contract->issuer,actor)||person(contract->assignee,actor)||(contract->executor_actor_id&&*contract->executor_actor_id==actor)));if(!involved)continue;related.insert(task.id);if(!terminal(task))pending(task.id);if(!task.budget_wallet_id.empty()){const auto* wallet=c.wallet(task.budget_wallet_id);if(!wallet||!owner_equal(wallet->owner,Owner{Owner::Kind::task,task.id,{}}))return fail("TaskEscrowOwnerMismatch",task.id);if(wallet->balance!=0||!wallet->reserved.empty())pending(task.id);}}
    if(tasks.state_need_tasks)for(const auto&row:tasks.state_need_tasks->contracts.rows()){const auto&contract=row.second;if(person(contract.assignee,actor)||person(contract.money.issuer,actor)||contract.executor_actor_id==actor){if(!tasks.tasks.find(contract.task_id))return fail("StateTaskSourceMissing",row.first);related.insert(contract.task_id);if(contract.phase!=StateTaskContractPhase::closed){pending(contract.id);pending(contract.task_id);}}}
    for(const auto& row:tasks.contracts.rows()){const auto& contract=row.second;bool involved=person(contract.issuer,actor)||person(contract.assignee,actor)||(contract.executor_actor_id&&*contract.executor_actor_id==actor);if(contract.current_task_id&&related.count(*contract.current_task_id))involved=true;for(const auto& id:contract.historical_task_ids)if(related.count(id))involved=true;if(!involved)continue;if(contract.id!=row.first||!contract.current_task_id||!tasks.tasks.find(*contract.current_task_id))return fail("InvalidTaskContract",row.first);if(contract.status!=ContractStatus::settled||!contract.settlement_id)pending(contract.id);}
    for(const auto& row:tasks.actions.rows()){const auto* action=c.action(row.first);const auto* task=tasks.tasks.find(row.second.task_id);if(!action||!task)return fail("InvalidTaskAction",row.first);if(related.count(task->id)||action->actor_id==actor||std::find(action->participants.begin(),action->participants.end(),actor)!=action->participants.end())pending(row.first);}
    // 受托货物即使Task已终态仍须先清算；容器为本人而货权为别人Task也不能一起遗赠。
    for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.owner.kind==Owner::Kind::task){if(!tasks.tasks.find(lot.owner.id))return fail("UnboundTaskCargo",lot.id);if(related.count(lot.owner.id)||person(row.second.owner,actor))pending(lot.id);}
    for(const auto& row:c.state().wallets.rows())if(person(row.second.owner,actor))for(const auto& reservation:row.second.reserved){if(reservation.action_id.kind!=ReservationRef::Kind::action)continue;const auto& action_id=reservation.action_id.id;const auto* params=tasks.actions.find(action_id);if(params){if(!c.action(action_id)||!tasks.tasks.find(params->task_id))return fail("InvalidTaskAction",action_id);pending(action_id);}}
    if(tasks.personal_advances){for(const auto& row:tasks.personal_advances->terms.rows()){const auto& terms=row.second;const auto* contract=tasks.contracts.find(row.first);if(!contract)return fail("InvalidTaskAdvanceContract",row.first);if(terms.lender_actor_id!=actor&&!person(terms.original_issuer,actor))continue;auto summary=read_task_personal_advance_summary(c,tasks,*tasks.personal_advances,row.first);if(!summary.ok)return {false,{},summary.error};if(summary.value.paid>summary.value.repaid){pending(row.first);for(const auto& id:summary.value.payment_fact_ids)pending(id);}}}
    // 旧Shipment只验证来源引用而未证明终结，不能信任自由字符串status作私产放行依据。
    for(const auto& row:tasks.shipments.rows()){const auto& shipment=row.second;const auto* task=shipment.cargo_owner.kind==Owner::Kind::task?tasks.tasks.find(shipment.cargo_owner.id):nullptr;if(shipment.id!=row.first||!task)return fail("InvalidTaskShipment",row.first);bool involved=related.count(task->id)||person(shipment.carrier_ref,actor);for(const auto& id:{shipment.source_inventory_id,shipment.cargo_inventory_id,shipment.destination_inventory_id}){if(id.empty())continue;const auto* inventory=c.inventory(id);if(!inventory)return fail("MissingTaskShipmentInventory",id);involved=involved||person(inventory->owner,actor);}if(involved)pending(row.first);}
    for(const auto& row:tasks.cargo_exposures.rows()){const auto& exposure=row.second;if(exposure.resolution==TaskCargoResolution::pending&&(related.count(exposure.task_id)||exposure.carrier_actor_id==actor||exposure.recipient_actor_id==actor))pending(row.first);}
    if(tasks.shop_orders){auto pending_orders=read_task_shop_order_actor_pending(c,tasks,*tasks.shop_orders,actor);if(!pending_orders.ok)return {false,{},pending_orders.error};for(const auto& source:pending_orders.value)pending(source);}
    return {true,std::move(out),{}};
}
}
